using System.ComponentModel.DataAnnotations.Schema;

namespace CatalogCart.Web.Models;

/// <summary>
/// A product as the app uses it. Also the EF Core entity for the
/// offline SQLite cache, so we don't need a separate database model.
/// </summary>
public class Product
{
    /// <summary>The product id from the API. Stored as-is, not generated by the database.</summary>
    [DatabaseGenerated(DatabaseGeneratedOption.None)]
    public int Id { get; set; }

    public string Name { get; set; } = string.Empty;

    public string Sku { get; set; } = string.Empty;

    /// <summary>Product type from the API, e.g. "variable", "simple" or "composite".</summary>
    public string Type { get; set; } = string.Empty;

    public decimal Price { get; set; }

    public int? StockQuantity { get; set; }

    public bool InStock { get; set; }

    /// <summary>Only used for a product with no variations; otherwise each UOM has its own.</summary>
    public bool BackordersAllowed { get; set; }

    public string? ImageUrl { get; set; }

    /// <summary>Position in the API's listing, so the offline catalog keeps the same order.</summary>
    public int SortOrder { get; set; }

    /// <summary>Each variation is one unit of measurement (UOM) with its own price.</summary>
    public List<ProductVariation> Variations { get; set; } = [];

    [NotMapped]
    public bool IsVariable => string.Equals(Type, ProductTypes.Variable, StringComparison.OrdinalIgnoreCase);
}

public static class ProductTypes
{
    public const string Variable = "variable";
}
